import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import {
  cp,
  mkdir,
  mkdtemp,
  readFile,
  rm,
  symlink,
  writeFile,
} from "node:fs/promises";
import { tmpdir } from "node:os";
import { delimiter, dirname, join } from "node:path";
import test from "node:test";
import {
  APP_DIRECTORY,
  checkMainnetRelease,
  readMainnetInput,
  validateMainnetInput,
} from "./mainnet-release.mjs";

// Public points only. No signer or private material is generated by these tests.
const complete = {
  programId: "5oEzAP4izB65uRm2yDAEf9oALGwHpWkDfyKb8zBY3euC",
  dbcConfig: "5w5aSyzkAmgYBcG3qop5EuLgpbMhAe7rnneuFkGjYKYc",
  landing: {
    tipLamports: 1_230_000,
    maxComputeUnitPriceMicroLamports: 450_000,
  },
};
const pending = {
  programId: null,
  dbcConfig: null,
  landing: { tipLamports: null, maxComputeUnitPriceMicroLamports: null },
};
const clone = (value) => structuredClone(value);

test("public mainnet release input has no inferred defaults", () => {
  assert.deepEqual(validateMainnetInput(complete).input, complete);
  assert.throws(
    () => validateMainnetInput(pending),
    /Mainnet release is PENDING/,
  );
  assert.equal(
    validateMainnetInput(pending, { allowPending: true }).pending.length,
    4,
  );
  for (const field of ["programId", "dbcConfig"]) {
    for (const value of [
      null,
      "PENDING",
      "11111111111111111111111111111111",
      "DoNH1Cxvv9umyWV9i77LEK4CoqTotDxPRzPxPBzjMJpe",
      "DzMTD92EwiEaZ5uTKPwweR2JEhp62kp8VEmpueCAQigr",
      "AonXiWUzyniqiaVyK7Bd8kjavgX6KBissnSmWwzVhX8k",
      [],
      1,
    ]) {
      assert.throws(() =>
        validateMainnetInput({ ...complete, [field]: value }),
      );
    }
  }
  assert.throws(
    () => validateMainnetInput({ ...complete, dbcConfig: complete.programId }),
    /distinct/,
  );
});

test("rejects extra fields, private material, invalid numeric units and incomplete measures", () => {
  for (const value of [
    [],
    null,
    { ...complete, secret: "unexpected" },
    { ...complete, landing: { ...complete.landing, extra: 1 } },
  ])
    assert.throws(() => validateMainnetInput(value), /must contain exactly/);
  for (const field of ["tipLamports", "maxComputeUnitPriceMicroLamports"]) {
    for (const value of [
      null,
      "1000000",
      0,
      -10_000,
      1.2,
      1_000_001,
      Number.MAX_SAFE_INTEGER,
      Infinity,
      NaN,
    ]) {
      const input = clone(complete);
      input.landing[field] = value;
      assert.throws(() => validateMainnetInput(input));
    }
  }
  const belowFloor = clone(complete);
  belowFloor.landing.tipLamports = 990_000;
  assert.throws(() => validateMainnetInput(belowFloor), /at least 1,000,000/);
});

test("checked-in pins remain synchronized whether public values are pending or supplied", async () => {
  const result = await checkMainnetRelease(APP_DIRECTORY, {
    allowPending: true,
  });
  assert.deepEqual(
    result,
    await readMainnetInput(APP_DIRECTORY, { allowPending: true }),
  );
});

async function workspace(t) {
  const root = await mkdtemp(join(tmpdir(), "onepercent-public-release-"));
  t.after(() => rm(root, { force: true, recursive: true }));
  const app = join(root, "app");
  for (const path of [
    "package.json",
    "Anchor.toml",
    "release/mainnet.json",
    "scripts/mainnet-release.mjs",
    "scripts/mainnet-pins.mjs",
    "scripts/params-rs.ts",
    "scripts/anchor-cluster.mjs",
    "scripts/program-release-check.mjs",
    "scripts/program.mjs",
    "packages/config/src",
    "programs/onepercent/src/lib.rs",
    "programs/onepercent/src/params.rs",
    "../docs/codex/PARAMS.md",
  ]) {
    await mkdir(dirname(join(app, path)), { recursive: true });
    await cp(join(APP_DIRECTORY, path), join(app, path), { recursive: true });
  }
  await symlink(
    join(APP_DIRECTORY, "node_modules"),
    join(app, "node_modules"),
    "dir",
  );
  await symlink(
    join(APP_DIRECTORY, "packages/config/node_modules"),
    join(app, "packages/config/node_modules"),
    "dir",
  );
  return app;
}
const run = (app, args, env = {}) =>
  spawnSync(process.execPath, args, {
    cwd: app,
    encoding: "utf8",
    env: { ...process.env, ONEPERCENT_CLUSTER: "localnet", ...env },
  });

test("apply supplied public values propagates every consumer and passes mainnet release identity checks", async (t) => {
  const app = await workspace(t);
  const input = join(app, "supplied.json");
  await writeFile(input, JSON.stringify(complete));
  const applied = run(app, [
    "scripts/mainnet-release.mjs",
    "apply",
    "--input",
    input,
  ]);
  assert.equal(applied.status, 0, applied.stderr + applied.stdout);
  assert.deepEqual((await checkMainnetRelease(app)).input, complete);
  assert.match(
    await readFile(join(app, "programs/onepercent/src/lib.rs"), "utf8"),
    new RegExp(`declare_id!\\("${complete.programId}"\\)`),
  );
  assert.match(
    await readFile(join(app, "programs/onepercent/src/params.rs"), "utf8"),
    new RegExp(complete.dbcConfig),
  );
  assert.match(
    await readFile(join(app, "Anchor.toml"), "utf8"),
    new RegExp(`\\[programs.mainnet\\]\\nonepercent = "${complete.programId}"`),
  );
  assert.match(
    await readFile(join(app, "../docs/codex/PARAMS.md"), "utf8"),
    /`maxComputeUnitPriceMicroLamports`|`landing.maxComputeUnitPriceMicroLamports`/,
  );
  const config = run(app, [
    "--import",
    "tsx",
    "--input-type=module",
    "-e",
    'import {MAINNET_RELEASE,ONEPERCENT_PROGRAM_IDS,SERVICES,meteoraForCluster} from "./packages/config/src/index.ts"; console.log(JSON.stringify({id:ONEPERCENT_PROGRAM_IDS.mainnet,dbc:meteoraForCluster("mainnet").dbcConfig,landing:SERVICES.landing,pin:MAINNET_RELEASE}));',
  ]);
  assert.equal(config.status, 0, config.stderr);
  const parsed = JSON.parse(config.stdout);
  assert.equal(parsed.id, complete.programId);
  assert.equal(parsed.dbc, complete.dbcConfig);
  assert.equal(parsed.landing.tipLamports, complete.landing.tipLamports);
  assert.equal(
    parsed.landing.maxComputeUnitPriceMicroLamports,
    complete.landing.maxComputeUnitPriceMicroLamports,
  );
  const bin = join(app, "bin");
  await mkdir(bin);
  await writeFile(
    join(bin, "cargo"),
    `#!${process.execPath}\nif (!process.argv.includes("mainnet")) process.exit(2); console.log("${complete.programId} ${complete.dbcConfig}");\n`,
    { mode: 0o700 },
  );
  const release = run(
    app,
    ["scripts/program-release-check.mjs", "--cluster", "mainnet-beta"],
    { PATH: bin + delimiter + process.env.PATH },
  );
  assert.equal(release.status, 0, release.stderr + release.stdout);
  assert.match(release.stdout, /Compiled identity \(mainnet\)/);
  await writeFile(
    join(app, "release/mainnet.json"),
    JSON.stringify(
      {
        ...complete,
        landing: { ...complete.landing, tipLamports: 1_240_000 },
      },
      null,
      2,
    ) + "\n",
  );
  await assert.rejects(checkMainnetRelease(app), /stale/);
});

test("apply refuses an incomplete input before writing any generated artifact", async (t) => {
  const app = await workspace(t);
  const lib = join(app, "programs/onepercent/src/lib.rs");
  const before = await readFile(lib);
  const input = join(app, "supplied.json");
  await writeFile(input, JSON.stringify(pending));
  const result = run(app, [
    "scripts/mainnet-release.mjs",
    "apply",
    "--input",
    input,
  ]);
  assert.notEqual(result.status, 0);
  assert.match(result.stderr, /Mainnet release is PENDING/);
  assert.deepEqual(await readFile(lib), before);
});
